// 일정 상세 모달
import { useState, useEffect, useRef } from 'react';
import type { ScheduleEvent, RecurrenceRule } from '../types';
import { useDraggable } from '../hooks/useDraggable';
import './EventModal.css';

interface EventModalProps {
  event: ScheduleEvent | null;
  isOpen: boolean;
  onClose: () => void;
  onSave: (event: ScheduleEvent) => void;
  onDelete: (eventId: string) => void;
  onCreateRecurring?: (
    title: string,
    start: string,
    end: string,
    color: string,
    note: string,
    rule: RecurrenceRule
  ) => void;
}

// 채도 낮은 파스텔 색상들 (15개)
const COLORS = [
  '#a5b4fc', // 연보라 (indigo)
  '#93c5fd', // 연파랑 (blue)
  '#7dd3fc', // 연하늘 (sky)
  '#67e8f9', // 연청록 (cyan)
  '#5eead4', // 연민트 (teal)
  '#86efac', // 연초록 (green)
  '#a3e635', // 연라임 (lime)
  '#fde68a', // 연노랑 (yellow)
  '#fcd34d', // 연금색 (amber)
  '#fed7aa', // 연주황 (orange)
  '#fca5a5', // 연빨강 (red)
  '#fda4af', // 연장미 (rose)
  '#f9a8d4', // 연분홍 (pink)
  '#c4b5fd', // 연보라 (purple)
  '#cbd5e1', // 연회색 (slate)
];

const WEEKDAYS = [
  { key: 'mon', label: '월' },
  { key: 'tue', label: '화' },
  { key: 'wed', label: '수' },
  { key: 'thu', label: '목' },
  { key: 'fri', label: '금' },
  { key: 'sat', label: '토' },
  { key: 'sun', label: '일' },
];

export default function EventModal({
  event,
  isOpen,
  onClose,
  onSave,
  onDelete,
  onCreateRecurring,
}: EventModalProps) {
  const [title, setTitle] = useState('');
  const [color, setColor] = useState(COLORS[0]);
  const [note, setNote] = useState('');
  const [startDate, setStartDate] = useState('');
  const [startTime, setStartTime] = useState('');
  const [endDate, setEndDate] = useState('');
  const [endTime, setEndTime] = useState('');
  const [isAllDay, setIsAllDay] = useState(false);
  
  // 반복 설정
  const [isRecurring, setIsRecurring] = useState(false);
  const [frequency, setFrequency] = useState<'daily' | 'weekly' | 'monthly'>('weekly');
  const [interval, setInterval] = useState(1);
  const [selectedDays, setSelectedDays] = useState<string[]>(['mon', 'tue', 'wed', 'thu', 'fri']);
  const [recurrenceEndDate, setRecurrenceEndDate] = useState('');
  
  const titleRef = useRef<HTMLInputElement>(null);
  const { position, isDragging, handleMouseDown, resetPosition } = useDraggable('event');

  useEffect(() => {
    if (event) {
      setTitle(event.title);
      setColor(event.color);
      setNote(event.note);
      setStartDate(event.date);
      setStartTime(event.start);
      setEndDate(event.endDate || event.date);
      setEndTime(event.end);
      setIsRecurring(false);
      // 종일 여부 판단 (isAllDay 플래그 또는 00:00~00:00)
      const isEventAllDay = event.isAllDay || (event.start === '00:00' && event.end === '00:00');
      setIsAllDay(isEventAllDay);
    }
  }, [event]);

  useEffect(() => {
    if (isOpen && titleRef.current) {
      titleRef.current.focus();
      titleRef.current.select();
      resetPosition();
    }
  }, [isOpen, resetPosition]);

  // 시작/종료 시간 유효성 검사
  const isTimeValid = () => {
    if (isAllDay) return true; // 종일이면 시간 검증 불필요
    if (!startDate || !endDate || !startTime || !endTime) return false; // 시간 필수
    
    const startDateTime = new Date(`${startDate}T${startTime}`);
    const endDateTime = new Date(`${endDate}T${endTime}`);
    
    return endDateTime > startDateTime;
  };

  // 종일 토글 처리
  const handleAllDayToggle = (checked: boolean) => {
    setIsAllDay(checked);
    if (checked) {
      // 종일: 00:00 ~ 00:00 (다음날)
      // 하루 종일 = 당일 00:00 ~ 다음날 00:00 (24시간)
      setStartTime('00:00');
      setEndTime('00:00');
      // 하루 종일이면 endDate = startDate (같은 날짜, end시간 00:00 = 다음날 0시)
      // 여러 날이면 endDate = 마지막 날
      if (!endDate || endDate === startDate) {
        setEndDate(startDate); // 같은 날짜로 설정 (end 00:00 = 자정 = 다음날로 해석)
      }
    } else {
      // 종일 해제: 기본 시간으로 복원
      setStartTime('09:00');
      setEndTime('10:00');
      setEndDate(startDate);
    }
  };

  // 시작 날짜 변경 시 종료 날짜 자동 조정
  const handleStartDateChange = (value: string) => {
    setStartDate(value);
    if (endDate < value) {
      setEndDate(value);
    }
  };

  // 시작 시간 변경 시 종료 시간 자동 조정
  const handleStartTimeChange = (value: string) => {
    setStartTime(value);
    if (startDate === endDate && endTime <= value) {
      // 30분 추가
      const [h, m] = value.split(':').map(Number);
      const newMinutes = h * 60 + m + 30;
      const newH = Math.floor(newMinutes / 60) % 24;
      const newM = newMinutes % 60;
      setEndTime(`${String(newH).padStart(2, '0')}:${String(newM).padStart(2, '0')}`);
    }
  };

  // 종료 날짜 변경 시 유효성 확인
  const handleEndDateChange = (value: string) => {
    if (value >= startDate) {
      setEndDate(value);
    }
  };

  // 종료 시간 변경 시 유효성 확인
  const handleEndTimeChange = (value: string) => {
    if (startDate === endDate && value <= startTime) {
      // 같은 날짜인데 종료 시간이 시작 시간보다 이르면 무시
      return;
    }
    setEndTime(value);
  };

  const handleSave = () => {
    if (!event) {
      console.log('handleSave: event is null');
      return;
    }

    // 종일이 아닌데 시간이 없으면 저장 불가
    if (!isAllDay && (!startTime || !endTime)) {
      alert('시간을 입력해주세요. 종일 일정은 "종일" 체크박스를 선택하세요.');
      return;
    }

    console.log('handleSave called with:', { title, color, startTime, endTime, startDate, endDate, isAllDay });

    if (isRecurring && onCreateRecurring) {
      // 반복 이벤트로 저장
      const rule: RecurrenceRule = {
        frequency,
        interval,
        startDate: startDate,
        endDate: recurrenceEndDate || null,
      };
      
      // 주간 반복일 때만 days 추가
      if (frequency === 'weekly') {
        rule.days = selectedDays as ('mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun')[];
      }
      // 월간 반복일 때만 dayOfMonth 추가
      if (frequency === 'monthly') {
        rule.dayOfMonth = new Date(startDate).getDate();
      }
      
      onCreateRecurring(title, startTime, endTime, color, note, rule);
      onDelete(event.id); // 원래 단일 이벤트 삭제
    } else {
      // 일반 이벤트로 저장
      const eventToSave: ScheduleEvent = {
        ...event,
        date: startDate,
        title,
        color,
        note,
        start: isAllDay ? '00:00' : startTime,
        end: isAllDay ? '00:00' : endTime,
        isAllDay,
        updatedAt: Date.now(),
      };
      
      // endDate가 startDate와 다를 때만 추가 (undefined 방지)
      if (endDate !== startDate) {
        eventToSave.endDate = endDate;
      } else if (isAllDay) {
        // 종일인데 같은 날짜면 다음날로 설정
        const nextDay = new Date(startDate);
        nextDay.setDate(nextDay.getDate() + 1);
        eventToSave.endDate = nextDay.toISOString().split('T')[0];
      } else {
        delete eventToSave.endDate;
      }
      
      console.log('Saving event:', eventToSave);
      onSave(eventToSave);
    }
    onClose();
  };

  const handleDelete = () => {
    if (!event) return;
    if (confirm('이 일정을 삭제하시겠습니까?')) {
      onDelete(event.id);
      onClose();
    }
  };

  const toggleDay = (day: string) => {
    setSelectedDays(prev =>
      prev.includes(day)
        ? prev.filter(d => d !== day)
        : [...prev, day]
    );
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') {
      onClose();
    } else if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      handleSave();
    }
  };

  if (!isOpen || !event) return null;

  // 드래그된 위치가 있으면 적용
  const modalStyle = position ? {
    position: 'fixed' as const,
    left: position.x,
    top: position.y,
    margin: 0,
  } : undefined;

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div 
        className={`modal-content ${isDragging ? 'dragging' : ''}`}
        onClick={e => e.stopPropagation()}
        onKeyDown={handleKeyDown}
        style={modalStyle}
      >
        {/* 헤더 - 드래그 핸들 */}
        <div 
          className="modal-header draggable" 
          onMouseDown={handleMouseDown}
          style={{ borderLeftColor: color }}
        >
          <h2>일정 편집</h2>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          {/* 제목 */}
          <div className="form-group">
            <label>제목</label>
            <input
              ref={titleRef}
              type="text"
              value={title}
              onChange={e => setTitle(e.target.value)}
              onKeyDown={e => {
                if (e.key === 'Enter' && title.trim() && isTimeValid()) {
                  e.preventDefault();
                  handleSave();
                }
              }}
              placeholder="일정 제목"
            />
          </div>

          {/* 색상 */}
          <div className="form-group">
            <label>색상</label>
            <div className="color-picker">
              {COLORS.map(c => (
                <button
                  key={c}
                  className={`color-btn ${c === color ? 'selected' : ''}`}
                  style={{ backgroundColor: c }}
                  onClick={() => setColor(c)}
                />
              ))}
            </div>
          </div>

          {/* 종일 체크박스 */}
          <div className="form-group checkbox-group">
            <label className="checkbox-label">
              <input
                type="checkbox"
                checked={isAllDay}
                onChange={e => handleAllDayToggle(e.target.checked)}
              />
              종일
            </label>
          </div>

          {/* 기간 섹션 - TaskModal과 동일한 구조 */}
          <div className="form-group">
            <label>기간</label>
            <div className="datetime-inputs">
              <div className="datetime-field">
                <span className="datetime-label">시작</span>
                <input
                  type="date"
                  value={startDate}
                  onChange={e => handleStartDateChange(e.target.value)}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={startTime}
                    onChange={e => handleStartTimeChange(e.target.value)}
                    required
                  />
                )}
              </div>
              <div className="datetime-spacer" />
              <div className="datetime-field">
                <span className="datetime-label">
                  종료{!isTimeValid() && <span className="error-text"> !</span>}
                </span>
                <input
                  type="date"
                  value={endDate}
                  onChange={e => handleEndDateChange(e.target.value)}
                  min={startDate}
                />
                {!isAllDay && (
                  <input
                    type="time"
                    value={endTime}
                    onChange={e => handleEndTimeChange(e.target.value)}
                    min={startDate === endDate ? startTime : undefined}
                    required
                  />
                )}
              </div>
            </div>
          </div>

          {/* 반복 설정 */}
          {onCreateRecurring && (
            <div className="form-group">
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  checked={isRecurring}
                  onChange={e => setIsRecurring(e.target.checked)}
                />
                반복 일정으로 설정
              </label>

              {isRecurring && (
                <div className="recurrence-options">
                  <div className="form-row">
                    <select
                      value={frequency}
                      onChange={e => setFrequency(e.target.value as 'daily' | 'weekly' | 'monthly')}
                    >
                      <option value="daily">매일</option>
                      <option value="weekly">매주</option>
                      <option value="monthly">매월</option>
                    </select>
                    <input
                      type="number"
                      min="1"
                      max="99"
                      value={interval}
                      onChange={e => setInterval(parseInt(e.target.value) || 1)}
                      style={{ width: '60px' }}
                    />
                    <span>{frequency === 'daily' ? '일' : frequency === 'weekly' ? '주' : '개월'}마다</span>
                  </div>

                  {frequency === 'weekly' && (
                    <div className="weekday-picker">
                      {WEEKDAYS.map(({ key, label }) => (
                        <button
                          key={key}
                          type="button"
                          className={`weekday-btn ${selectedDays.includes(key) ? 'selected' : ''}`}
                          onClick={() => toggleDay(key)}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  )}

                  <div className="form-group">
                    <label>반복 종료일 (선택)</label>
                    <input
                      type="date"
                      value={recurrenceEndDate}
                      onChange={e => setRecurrenceEndDate(e.target.value)}
                    />
                  </div>
                </div>
              )}
            </div>
          )}

          {/* 메모 */}
          <div className="form-group">
            <label>메모</label>
            <textarea
              value={note}
              onChange={e => setNote(e.target.value)}
              placeholder="메모 추가..."
              rows={3}
            />
          </div>
        </div>

        <div className="modal-footer">
          <button className="delete-btn" onClick={handleDelete}>
            삭제
          </button>
          <div className="footer-right">
            <button className="cancel-btn" onClick={onClose}>
              취소
            </button>
            <button className="save-btn" onClick={handleSave} disabled={!isTimeValid()}>
              저장
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}
